SELECT id, ledger_book_id, chart_account_id, owner_type, owner_id, balance_bucket, normal_side, account_status, debit_total, credit_total, net_balance, last_journal_sequence, balance_version, create_time, update_time FROM t_account WHERE id IN
#{id}
ORDER BY id FOR UPDATE

SELECT id, ledger_book_id, chart_account_id, owner_type, owner_id, balance_bucket, normal_side, account_status, debit_total, credit_total, net_balance, last_journal_sequence, balance_version, create_time, update_time FROM t_account WHERE id IN
#{id}
ORDER BY id

mapper.update:
UPDATE t_account
SET debit_total = #{debitTotal}, credit_total = #{creditTotal}, net_balance = #{netBalance},
    last_journal_sequence = #{journalSequence}, balance_version = balance_version + 1, update_time = #{now}
WHERE id = #{account.id} AND balance_version = #{account.balanceVersion}
  AND last_journal_sequence < #{journalSequence}

mapper.select:
SELECT a.id account_id, c.account_code, a.owner_type, a.owner_id, a.balance_bucket, a.normal_side,
       a.account_status, a.debit_total, a.credit_total, a.net_balance, a.last_journal_sequence
FROM t_account a
JOIN t_chart_account c ON c.id = a.chart_account_id
WHERE a.ledger_book_id = #{query.ledgerBookId}
AND c.account_code = #{query.accountCode}
AND a.owner_type = #{query.ownerType}
AND a.owner_id = #{query.ownerId}
AND a.balance_bucket = #{query.balanceBucket}
ORDER BY c.account_code, a.owner_type, a.owner_id, a.balance_bucket, a.id
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM t_account a
JOIN t_chart_account c ON c.id = a.chart_account_id
WHERE a.ledger_book_id = #{query.ledgerBookId}
AND c.account_code = #{query.accountCode}
AND a.owner_type = #{query.ownerType}
AND a.owner_id = #{query.ownerId}
AND a.balance_bucket = #{query.balanceBucket}
